module KrakeNNONNXExt

# ONNX reader for feed-forward scalar laws (`load_onnx_law`, stub in
# src/platform/closures/onnx_stub.jl). Loaded by `using ProtoBuf` (weakdep).
#
# Decoder choice: ProtoBuf.jl message types generated by `protojl` from the
# trimmed schema ext/onnx_proto/onnx_subset.proto (same field numbers as the
# upstream onnx.proto; unknown fields are skipped on decode). The generated
# file is committed, so ProtoBuf.jl is the only runtime dependency and the
# ONNX schema is not re-fetched. Regenerate with
#   ProtoBuf.protojl("onnx_subset.proto", "ext/onnx_proto", "ext/onnx_proto")

using KrakeNN
using ProtoBuf

module OnnxPB
include("onnx_proto/onnx_subset_pb.jl")
end
const PB = ProtoBuf

# ---------------------------------------------------------------- tensors

_onnx_unsupported(op) = throw(ArgumentError(
    "ONNX op '$(op)' is not supported by load_onnx_law (supported: Gemm, MatMul+Add, " *
    "Tanh, Relu, Sigmoid, Softplus, Sub/Div by a constant at the input, Exp/Softplus at the output)"))

"""Tensor values as a `Vector{Float64}` in ONNX (row-major) element order."""
function _onnx_values(t::OnnxPB.TensorProto)
    dt = t.data_type
    if !isempty(t.raw_data)
        T = dt == 1 ? Float32 : dt == 11 ? Float64 : dt == 7 ? Int64 : dt == 6 ? Int32 :
            throw(ArgumentError("ONNX tensor '$(t.name)': unsupported data_type $(dt)"))
        return Float64.(collect(reinterpret(T, copy(t.raw_data))))
    end
    dt == 1 && return Float64.(t.float_data)
    dt == 11 && return Float64.(t.double_data)
    dt == 7 && return Float64.(t.int64_data)
    dt == 6 && return Float64.(t.int32_data)
    throw(ArgumentError("ONNX tensor '$(t.name)': unsupported data_type $(dt)"))
end

struct _Tensor
    dims::Vector{Int}
    values::Vector{Float64}   # row-major
end
_tensor(t::OnnxPB.TensorProto) = _Tensor(Int.(t.dims), _onnx_values(t))

function _attr(node::OnnxPB.NodeProto, name::AbstractString, default)
    for a in node.attribute
        a.name == name || continue
        default isa Integer && return Int(a.i)
        default isa AbstractFloat && return Float64(a.f)
        return a
    end
    return default
end

# Matrix (out × in) from a Gemm/MatMul weight. `stored_out_in` is true when
# ONNX stores it as [out, in] (Gemm with transB=1), false for [in, out].
function _weight(t::_Tensor, stored_out_in::Bool)
    length(t.dims) == 2 || throw(ArgumentError("ONNX weight must be a matrix, got dims $(t.dims)"))
    r, c = t.dims
    M = reshape(t.values, c, r)'   # row-major r × c -> Julia matrix r × c
    return stored_out_in ? Matrix(M) : Matrix(M')
end

# ---------------------------------------------------------------- parsing

mutable struct _Layer
    W::Matrix{Float64}
    b::Vector{Float64}
    act::Symbol            # :none until an activation node follows
end

function KrakeNN.load_onnx_law(path::AbstractString; kw...)
    bytes = read(path)
    model = PB.decode(PB.ProtoDecoder(IOBuffer(bytes)), OnnxPB.ModelProto)
    return _law_from_graph(model.graph; kw...)
end

function _law_from_graph(g::OnnxPB.GraphProto; kw...)
    consts = Dict{String,_Tensor}()
    for t in g.initializer
        consts[t.name] = _tensor(t)
    end
    for n in g.node
        n.op_type == "Constant" || continue
        for a in n.attribute
            a.name == "value" && (consts[n.output[1]] = _tensor(a.t))
        end
    end
    inputs = [v.name for v in g.input if !haskey(consts, v.name)]
    length(inputs) == 1 || throw(ArgumentError("ONNX graph must have exactly one non-constant input, got $(inputs)"))
    cur = inputs[1]

    shift = nothing; scale = nothing
    layers = _Layer[]
    pending = nothing   # MatMul weight waiting for its Add

    flush_pending!() = if pending !== nothing
        push!(layers, _Layer(pending, zeros(size(pending, 1)), :none))
        pending = nothing
    end
    function data_and_const(n)
        length(n.input) == 2 || throw(ArgumentError("ONNX node '$(n.op_type)' expects two inputs"))
        i = findfirst(==(cur), n.input)
        i === nothing && throw(ArgumentError("ONNX graph is not a linear chain at node '$(n.op_type)' ($(n.name))"))
        c = n.input[3-i]
        haskey(consts, c) || throw(ArgumentError("ONNX node '$(n.op_type)' needs a constant second operand"))
        return i, consts[c]
    end

    for n in g.node
        op = n.op_type
        op == "Constant" && continue
        if op == "Gemm"
            flush_pending!()
            cur in n.input[1:1] || throw(ArgumentError("ONNX graph is not a linear chain at Gemm ($(n.name))"))
            _attr(n, "transA", 0) == 0 || _onnx_unsupported("Gemm(transA=1)")
            alpha = _attr(n, "alpha", 1.0); beta = _attr(n, "beta", 1.0)
            transB = _attr(n, "transB", 0) == 1
            haskey(consts, n.input[2]) || throw(ArgumentError("Gemm weight must be a constant"))
            W = alpha .* _weight(consts[n.input[2]], transB)
            b = length(n.input) >= 3 && !isempty(n.input[3]) ?
                beta .* consts[n.input[3]].values : zeros(size(W, 1))
            length(b) == size(W, 1) || throw(ArgumentError("Gemm bias length $(length(b)) != $(size(W,1))"))
            push!(layers, _Layer(W, b, :none))
        elseif op == "MatMul"
            flush_pending!()
            n.input[1] == cur && haskey(consts, n.input[2]) ||
                throw(ArgumentError("MatMul must be (data, constant weight)"))
            pending = _weight(consts[n.input[2]], false)
        elseif op == "Add"
            _, c = data_and_const(n)
            pending === nothing && _onnx_unsupported("Add (not preceded by MatMul)")
            length(c.values) == size(pending, 1) || throw(ArgumentError("Add bias length mismatch"))
            push!(layers, _Layer(pending, copy(c.values), :none))
            pending = nothing
        elseif op in ("Sub", "Div")
            flush_pending!()
            isempty(layers) || _onnx_unsupported("$(op) after the first layer")
            i, c = data_and_const(n)
            i == 1 || _onnx_unsupported("$(op) with constant first operand")
            if op == "Sub"
                (shift === nothing && scale === nothing) ||
                    _onnx_unsupported("Sub after Div (input normalization must be (x-shift)/scale)")
                shift = c.values
            else
                scale === nothing || _onnx_unsupported("repeated Div")
                scale = c.values
            end
        elseif op in ("Tanh", "Relu", "Sigmoid", "Softplus", "Exp")
            flush_pending!()
            isempty(layers) && _onnx_unsupported("$(op) before the first layer")
            layers[end].act === :none || _onnx_unsupported("$(op) after another activation")
            layers[end].act = Symbol(lowercase(op))
        else
            _onnx_unsupported(op)
        end
        length(n.output) >= 1 && (cur = n.output[1])
    end
    flush_pending!()

    isempty(layers) && throw(ArgumentError("ONNX graph has no Gemm/MatMul layer"))
    for k in 1:length(layers)-1
        layers[k].act === :exp && _onnx_unsupported("Exp on a hidden layer")
        layers[k].act === :none && (layers[k].act = :identity)
    end
    out = layers[end]
    size(out.W, 1) == 1 || throw(ArgumentError("output layer must have width 1, got $(size(out.W, 1))"))
    out.act === :none && (out.act = :identity)
    out.act in (:identity, :exp, :softplus) ||
        _onnx_unsupported("$(titlecase(string(out.act))) at the output (allowed: Exp, Softplus)")

    nin = size(layers[1].W, 2)
    for k in 2:length(layers)
        size(layers[k].W, 2) == size(layers[k-1].W, 1) ||
            throw(ArgumentError("layer $(k) input width does not match layer $(k-1) output"))
    end
    bc(v, fill) = v === nothing ? ntuple(_ -> fill, nin) :
        length(v) == 1 ? ntuple(_ -> v[1], nin) :
        length(v) == nin ? ntuple(i -> v[i], nin) :
        throw(ArgumentError("input normalization constant has length $(length(v)), expected 1 or $(nin)"))
    law = KrakeNN.DenseNet(nin, Tuple(size(l.W, 1) for l in layers[1:end-1]);
                           activation=Tuple(l.act for l in layers[1:end-1]),
                           output=out.act, shift=bc(shift, 0.0), scale=bc(scale, 1.0), kw...)
    theta = Float64[]
    for l in layers
        append!(theta, vec(l.W))   # column-major out × in, as DenseNet expects
        append!(theta, l.b)
    end
    length(theta) == KrakeNN.law_nparams(law) || error("internal: parameter count mismatch")
    return law, theta
end

end
